+                // Data in order defined by Rectangle class
+                return new Rectangle(
+                    encoder.decodeX(ints[0]),
+                    encoder.decodeX(ints[1]),
+                    encoder.decodeY(ints[2]),
+                    encoder.decodeY(ints[3])
