+        testBoundsBlockLoaderAux(encoder, geometries, indexerFactory, visitor, rectangleMaker);
+    }
+
+    private static void testBoundsBlockLoaderAux(
+        CoordinateEncoder encoder,
+        java.util.List<Geometry> geometries,
